const prompt = (a) => `You are agent "${a.key}" in refactor audit 2 of the rv-connect repository at ${ROOT}.

FIRST read ${AUD}/brief-common.md in full. It is the owner's intent in his own words, the hard rules (read-only; no builds, no tsc, no knip, no browsers, no database, no network unless your charter grants it; never write anywhere but your report), what the first audit already settled, the methodology (reduction order, anti-gaming, the six bloat signatures, tiering), the raw tool outputs on disk, the exact finding format and the report structure. It binds you. Then read ${ROOT}/CLAUDE.md and ${ROOT}/AGENTS.md.

YOUR CHARTER: ${a.charter}

YOUR TERRITORY (read every file in full unless the charter says classification-level): ${a.files}

NOT YOURS (do not audit; but cross-boundary duplication you notice goes under "For other lenses" with both file names): ${a.notYours}

READ THESE SPECS BEFORE JUDGING ANYTHING: ${a.specs}

LEADS FROM THE RAW TOOL OUTPUT (${AUD}/raw/): ${a.leads}

QUESTIONS YOU MUST ANSWER EXPLICITLY IN THE REPORT (a floor, not a ceiling — hunt beyond them): ${a.questions}

WRITE YOUR REPORT to ${AUD}/agents/${a.key}.md using the brief's section-9 structure and section-8 finding format, ids ${a.key}-01 upward, biggest structural wins first, every finding with its honest unit of saving, its gate, and autonomous-vs-owner. Write a partial report early if the territory is large, then overwrite it with the full one. The report on disk is the deliverable; the session may die at any moment and only the file survives. When the report is complete, return the structured summary (key, reportPath, counts, headline, gaps).`

phase('Find')
const todo = AGENTS.filter((a) => !done.has(a.key))
log(`launching ${todo.length} agents in waves of 6 (skipping ${done.size}: ${[...done].join(', ') || 'none'})`)
const summaries = []
for (let i = 0; i < todo.length; i += 6) {
  const wave = todo.slice(i, i + 6)
  log(`wave ${i / 6 + 1}: ${wave.map((a) => a.key).join(', ')}`)
  const results = await parallel(wave.map((a) => () => agent(prompt(a), { label: a.key, phase: 'Find', schema: SUMMARY })))
  const ok = results.filter(Boolean)
  summaries.push(...ok)
  log(`wave ${i / 6 + 1} done: ${ok.length}/${wave.length} returned; ${summaries.length} total so far`)
  if (wave.length > 1 && results.every((r) => !r)) {
    log('entire wave returned nothing — stopping so later waves are not fed into a dead usage limit')
    break
  }
}
return { returned: summaries.length, summaries }
